const abyssSpiritSheet=new Image();abyssSpiritSheet.assetSrc='assets/abyss-spirit-v2.png';
const abyssSpiritLinks=new WeakMap();
function abyssSpiritEligible(e,ally){return ally!==e&&!ally.boss&&ally.hp>0&&Number.isFinite(ally.max)&&ally.max>ally.hp&&dist(e,ally)<=300&&lineClear(e,ally);}
function beginAbyssSpirit(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'abyssMending',bespoke:true,windup:1.2,origin:{x:e.x,y:e.y},healed:0,mended:false,target:{x:p.x,y:p.y},fired:false};abyssSpiritLinks.set(e.attack,enemies.filter(ally=>abyssSpiritEligible(e,ally)).sort((a,b)=>dist(e,a)-dist(e,b)).slice(0,3));}
const abyssSpiritAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r11e7')return abyssSpiritAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='abyssMending'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=300&&clear){beginAbyssSpirit(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,64*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed+=dt;
 if(!a.mended&&e.elapsed+1e-8>=1.2){a.mended=true;for(let ally of abyssSpiritLinks.get(a)||[]){if(!enemies.includes(ally)||!abyssSpiritEligible(e,ally))continue;let amount=Math.min(ally.max-ally.hp,ally.max*.2);if(amount>0){ally.hp+=amount;ally.flash=.18;a.healed++;}}playSound('impact',e.x,e.y);}
 if(!a.fired&&e.elapsed+1e-8>=2.4){a.fired=true;e.struck=true;if(dist(a.target,p)<=140&&lineClear(a.origin,a.target)&&lineClear(a.target,p))hurt(60+a.healed*20);playSound('impact',e.x,e.y);}
 if(e.elapsed>=3.4){e.attack=null;e.state='idle';e.t=3.5;}
};
const abyssSpiritDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r11e7'||!abyssSpiritSheet.complete||!abyssSpiritSheet.naturalWidth||!abyssSpiritSheet.naturalHeight)return abyssSpiritDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),a=e.attack;if(e.hp<=0)f={row:2,col:3};else if(a?.pattern==='abyssMending')f={row:2,col:e.elapsed<1.2?0:e.elapsed<2.4?1:e.elapsed<2.65?2:3};let q=project(e.x,e.y),sw=abyssSpiritSheet.naturalWidth/4,sh=abyssSpiritSheet.naturalHeight/3,w=270,h=w*sh/sw,anchor=[[.89,.89,.89,.89],[.8,.8,.8,.8],[.77,.77,.77,.77]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y-12-Math.sin((e.anim||0)*2)*3);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,abyssSpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(abyssSpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const abyssSpiritSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r11e7'?175:abyssSpiritSizeBase(e);
const abyssSpiritGroundBase=drawGroundEffects;drawGroundEffects=()=>{abyssSpiritGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r11e7'):enemies)){let a=e.attack;if(e.species!=='r11e7'||e.hp<=0||a?.pattern!=='abyssMending'||!visibleAt(e.x,e.y))continue;if(!a.mended){let q=project(e.x,e.y);for(let ally of abyssSpiritLinks.get(a)||[]){if(!enemies.includes(ally)||!abyssSpiritEligible(e,ally))continue;groundRing(ally.x,ally.y,32,'#8af0ce',2);let v=project(ally.x,ally.y);ctx.save();ctx.strokeStyle='#8af0ce';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(q.x,q.y-20);ctx.lineTo(v.x,v.y-20);ctx.stroke();ctx.restore();}}if(e.elapsed<2.7){groundRing(a.target.x,a.target.y,140,a.fired?'#f7d2ff':'#ca9cdb',2+a.healed);if(!a.fired)groundRing(a.target.x,a.target.y,140*Math.min(1,e.elapsed/2.4),'#c39be0',1);}}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r11e7',animateEnemy,drawRegionEnemy);
